// IFMOSPHERE SPEC RENDERER (template, copied into every episode as src/episodes/<slug>/render.tsx by Hark).
// It turns shots.json (written by Hark) into shots: layered parallax sets, an eased camera move, Pip with
// anticipation / overshoot / settle and secondary motion, the cast, props, and brand text in fixed safe-area slots.
// The episode supplies only the vocabulary: SETS, PROPS, ACTIONS, CUSTOM (sets.tsx / props.tsx / custom.tsx).
// Do not edit this file in an episode; if a shot needs something it can't do, write a CUSTOM shot for that id.
import React from 'react';
import { ShotMap, ShotProps, clamp, lerp, easeInOut, easeOut, backOut, settle } from '../../engine';
import {
  Pip, pipPose, PipLocal, CastMember, BrandPill, BrandLabel, BrandChip, BrandChapter, BrandTitle, PALETTE,
  feetBelowHips, faceAt, walkPose, joints, toWorld,
} from '../../brand';
import type { Pose, Expr, PipPoseName, RimId, CastMemberName } from '../../brand';

// ---------------------------------------------------------------- the shots.json contract
export type V3 = [number, number, number]; // camera centre x, y (0..1 of the frame) and zoom
export type TextColor = 'cream' | 'orange' | 'gold' | 'sky' | 'cyan' | 'green' | 'red';
export type Slot = 'tl' | 'tr' | 'bl' | 'br' | 'top' | 'mid' | 'center' | 'bottom';
export type TextSpec = {
  kind: 'pill' | 'label' | 'chip' | 'chapter' | 'title' | 'big';
  slot?: Slot; text?: string; label?: string; value?: string; sub?: string; color?: TextColor; at?: number;
  lines?: [string, string]; accent?: string[];
};
export type PipSpec = {
  x: number; x2?: number; s?: number; lift?: number; pose?: PipPoseName; to?: PipPoseName; expr?: Expr; expr2?: Expr;
  at2?: number; act?: string; facing?: 1 | -1; rim?: RimId; held?: string; heldp?: Record<string, unknown>;
  over?: string; overp?: Record<string, unknown>; // an overlay prop drawn on Pip via <PipLocal> (helmet ring, backpack)
};
export type CastSpec = { name: CastMemberName; x: number; s?: number; pose?: PipPoseName; expr?: Expr; facing?: 1 | -1 };
export type PropSpec = { k: string; x: number; y: number; s?: number; p?: Record<string, unknown>; z?: 'back' | 'mid' | 'front' };
export type SegSpec = {
  id: string; ch: number; vo?: string; dir?: string; set: string; setp?: Record<string, unknown>;
  cam?: [V3] | [V3, V3]; ease?: 'inOut' | 'out' | 'in' | 'linear';
  pip?: PipSpec | null; cast?: CastSpec[]; props?: PropSpec[]; text?: TextSpec[]; custom?: string; shake?: number;
};

// ---------------------------------------------------------------- what an episode supplies
export type Layer = 'far' | 'mid' | 'near';
export type SetProps = { t: number; len: number; p: number; W: number; H: number; ground: number; layer: Layer; sp: Record<string, unknown>; id: string };
export type PropProps = { t: number; len: number; p: number; pp: Record<string, unknown>; id: string };
export type ActionArgs = { from: Pose; to: Pose; t: number; len: number; p: number; ground: number; W: number; H: number; spec: PipSpec };
export type CustomProps = { t: number; len: number; p: number; W: number; H: number; seg: SegSpec };
export type Registry = {
  sets: Record<string, React.FC<SetProps>>; // draws ONE layer per call: far (sky, distant scenery), mid (room/ground/main scenery), near (foreground pieces)
  props: Record<string, React.FC<PropProps>>; // drawn around (0,0) at scale 1 (props in the world, held items, overlays)
  actions?: Record<string, (a: ActionArgs) => Pose>;
  custom?: Record<string, React.FC<CustomProps>>; // bespoke full-frame shots keyed by shot id (diagrams, maps, split screens)
};

const COLORS: Record<TextColor, string> = {
  cream: PALETTE.cream, orange: PALETTE.orange, gold: PALETTE.gold, sky: PALETTE.sky, cyan: PALETTE.cyan, green: PALETTE.green, red: PALETTE.red,
};
const EASE = { inOut: easeInOut, out: easeOut, in: (x: number) => x * x * x, linear: (x: number) => x };
const PARALLAX: Record<Layer, number> = { far: 0.3, mid: 1, near: 1.3 };

/** Camera for one depth layer: far layers move and zoom less than the world, near layers more (parallax). */
const camFor = (c: V3, layer: Layer, W: number, H: number) => {
  const k = PARALLAX[layer];
  const z = 1 + (c[2] - 1) * k;
  const cx = (0.5 + (c[0] - 0.5) * k) * W;
  const cy = (0.5 + (c[1] - 0.5) * k) * H;
  return `translate(${W / 2} ${H / 2}) scale(${z}) translate(${-cx} ${-cy})`;
};

/** Safe-area slots. 16:9 keeps 5% title-safe margins; 9:16 keeps clear of the Shorts UI (top 250, bottom 480, right 170)
 *  and of Pip: three text rows only (330, 560, 800). */
const slotXY = (slot: Slot, W: number, H: number): [number, number] => {
  if (H > W) {
    const m: Record<Slot, [number, number]> = {
      // Pip stands in the lower third (ground 0.74), so 'bottom' text sits above his head, never on his body
      tl: [455, 330], tr: [455, 330], top: [455, 330], mid: [455, 560], center: [455, 800], bl: [455, 800], br: [455, 800], bottom: [455, 800],
    };
    return m[slot];
  }
  const m: Record<Slot, [number, number]> = {
    tl: [420, 150], tr: [W - 420, 150], top: [W / 2, 150], mid: [W / 2, 320], center: [W / 2, H / 2], bl: [420, H - 150], br: [W - 420, H - 150], bottom: [W / 2, H - 140],
  };
  return m[slot];
};

const Texts: React.FC<{ texts: TextSpec[]; t: number; len: number; W: number; H: number; headTop?: number }> = ({ texts, t, len, W, H, headTop }) => {
  const vert = H > W;
  const k = vert ? 1.15 : 1;
  return (
    <g>
      {texts.map((x, i) => {
        const tt = t - (x.at ?? 0.12) * len;
        const col = COLORS[x.color ?? 'gold'];
        const [sx, sy0] = slotXY(x.slot ?? 'tr', W, H);
        // 9:16: the low row moves up (never above 640) so it can't sit on Pip's head in a close shot
        const sy = vert && headTop !== undefined && sy0 >= 800 && sy0 + 70 > headTop ? Math.max(640, headTop - 80) : sy0;
        if (x.kind === 'chapter') return <BrandChapter key={i} t={tt} title={x.text ?? ''} sub={x.sub ?? ''} color={col} x={vert ? 70 : 76} y={vert ? 260 : 82} />;
        if (x.kind === 'title') return <BrandTitle key={i} t={tt} lines={x.lines ?? ['WHAT IF YOU', x.text ?? '']} accentWords={x.accent ?? []} x={vert ? 455 : W / 2} y={vert ? 420 : 185} size={vert ? 76 : 112} />;
        if (x.kind === 'pill') return <BrandPill key={i} x={sx} y={sy} t={tt} label={x.label ?? ''} value={x.value ?? x.text ?? ''} color={col} scale={k} />;
        if (x.kind === 'chip') return <BrandChip key={i} x={sx} y={sy} t={tt} text={x.text ?? ''} color={col} />;
        if (x.kind === 'big') return <BrandLabel key={i} x={sx} y={sy + 30} t={tt} text={x.text ?? ''} size={vert ? 104 : 96} color={col} />;
        return <BrandLabel key={i} x={sx} y={sy} t={tt} text={x.text ?? ''} size={vert ? 50 : 44} color={col} />;
      })}
    </g>
  );
};

/** Pip's motion over one shot: anticipation, an overshooting move into the target pose, a settle, a walk if x moves,
 *  breathing, drawstring sway, and an expression swap through a blink. Episode actions replace the body motion. */
const pipMotion = (spec: PipSpec, t: number, len: number, W: number, H: number, ground: number, reg: Registry): Pose => {
  const s = (spec.s ?? 0.9) * Math.min(W, H) / 1080;
  const facing = spec.facing ?? 1;
  const gy = ground - feetBelowHips(s) - (spec.lift ?? 0) * H;
  const x0 = spec.x * W;
  const x1 = (spec.x2 ?? spec.x) * W;
  const from = pipPose(spec.pose ?? 'stand', { x: x0, y: gy, scale: s, facing });
  const to = pipPose(spec.to ?? spec.pose ?? 'stand', { x: x1, y: gy, scale: s, facing });
  const p = clamp(t / Math.max(1, len));
  let pose: Pose;
  const act = spec.act ? reg.actions?.[spec.act] : undefined;
  if (act) {
    pose = act({ from, to, t, len, p, ground, W, H, spec });
  } else if (Math.abs(x1 - x0) > 0.04 * W) {
    const xp = lerp(x0, x1, easeInOut(p));
    pose = walkPose(xp, (xp - x0) / (34 * s), ground, s, {}, x1 > x0 ? 1 : -1);
  } else {
    const a = clamp(p / 0.2); // anticipation dip
    const m = clamp((p - 0.2) / 0.3); // the move, with overshoot
    const mix = (u: number, v: number) => lerp(u, v, backOut(m));
    const limb = (k: 'armL' | 'armR' | 'legL' | 'legR') => ({ a: mix(from[k].a, to[k].a), b: mix(from[k].b, to[k].b) });
    pose = {
      ...from,
      ...(m > 0.5 ? { handL: to.handL, handR: to.handR } : {}),
      armL: limb('armL'), armR: limb('armR'), legL: limb('legL'), legR: limb('legR'),
      yaw: mix(from.yaw, to.yaw), look: mix(from.look, to.look), headTilt: mix(from.headTilt, to.headTilt) + settle(t - 0.5 * len, 4),
      tilt: mix(from.tilt, to.tilt), squash: (to.squash ?? 0) * m + 0.07 * Math.sin(Math.PI * a) * (1 - m),
    };
  }
  const fk: [number, Expr][] = [[0, spec.expr ?? 'neutral']];
  if (spec.expr2) fk.push([(spec.at2 ?? 0.55) * len, spec.expr2]);
  const f = faceAt(t, fk);
  return {
    ...pose,
    expr: f.expr,
    blink: Math.max(f.blink, t % 97 > 94 ? 1 : 0),
    squash: pose.squash + 0.012 * Math.sin(t / 8), // breathing
    sway: pose.sway + 9 * Math.sin(t / 6) + settle(t - 0.5 * len, 16), // drawstrings swing after the move
  };
};

const Missing: React.FC<{ what: string; W: number; H: number }> = ({ what, W, H }) => (
  <BrandLabel x={W / 2} y={H / 2} t={10} text={`MISSING ${what}`} size={52} color={PALETTE.red} />
);

const PropAt: React.FC<{ ps: PropSpec; reg: Registry; t: number; len: number; p: number; W: number; H: number; id: string }> = ({ ps, reg, t, len, p, W, H, id }) => {
  const P = reg.props[ps.k];
  if (!P) return <Missing what={`PROP ${ps.k}`} W={W} H={H} />;
  return (
    <g transform={`translate(${ps.x * W} ${ps.y * H}) scale(${(ps.s ?? 1) * Math.min(W, H) / 1080})`}>
      <P t={t} len={len} p={p} pp={ps.p ?? {}} id={id} />
    </g>
  );
};

export const SpecShot: React.FC<{ seg: SegSpec; reg: Registry; W: number; H: number } & ShotProps> = ({ seg, reg, W, H, t, len }) => {
  const p = clamp(t / Math.max(1, len));
  const ground = ((seg.setp?.ground as number | undefined) ?? (H > W ? 0.74 : 0.8)) * H;
  const c0 = seg.cam?.[0] ?? [0.5, 0.5, 1];
  const c1 = seg.cam?.[1] ?? [c0[0] + 0.01, c0[1] + 0.004, c0[2] * 1.05]; // never a static hold: default slow push-in
  const e = EASE[seg.ease ?? 'inOut'](p);
  const sh = seg.shake ? settle(t - seg.shake * len, 14, 2.6, 5) : 0;
  const cam: V3 = [lerp(c0[0], c1[0], e) + sh / W, lerp(c0[1], c1[1], e), lerp(c0[2], c1[2], e)];
  const id = seg.id;
  if (seg.custom) {
    const C = reg.custom?.[id];
    return (
      <g>
        {C ? <C t={t} len={len} p={p} W={W} H={H} seg={seg} /> : <Missing what={`CUSTOM ${id}`} W={W} H={H} />}
        <Texts texts={seg.text ?? []} t={t} len={len} W={W} H={H} />
      </g>
    );
  }
  const S = reg.sets[seg.set];
  const layer = (l: Layer, body: React.ReactNode) => <g transform={camFor(cam, l, W, H)}>{body}</g>;
  const setLayer = (l: Layer) => (S ? <S t={t} len={len} p={p} W={W} H={H} ground={ground} layer={l} sp={seg.setp ?? {}} id={`${id}${l}`} /> : null);
  const pose = seg.pip ? pipMotion(seg.pip, t, len, W, H, ground, reg) : null;
  const hand = pose && seg.pip?.held ? toWorld(pose, joints(pose).armR.end) : null;
  const Held = seg.pip?.held ? reg.props[seg.pip.held] : undefined;
  const Over = seg.pip?.over ? reg.props[seg.pip.over] : undefined;
  const props = seg.props ?? [];
  const pz = (z: PropSpec['z']) => props.filter((x) => (x.z ?? 'mid') === z).map((x, i) => <PropAt key={`${z}${i}`} ps={x} reg={reg} t={t} len={len} p={p} W={W} H={H} id={`${id}${z}${i}`} />);
  return (
    <g>
      {layer('far', setLayer('far'))}
      {layer('mid', (
        <g>
          {setLayer('mid')}
          {pz('back')}
          {(seg.cast ?? []).map((c, i) => {
            const s = (c.s ?? 0.88) * Math.min(W, H) / 1080;
            const cp = pipPose(c.pose ?? 'stand', { x: c.x * W, y: ground - feetBelowHips(s), scale: s, facing: c.facing ?? -1, expr: c.expr ?? 'happy', headTilt: settle(t, 5, 0.9, 12) });
            return <CastMember key={i} name={c.name} pose={{ ...cp, squash: 0.01 * Math.sin(t / 9 + i) }} rim={seg.pip?.rim ?? 'rimR'} />;
          })}
          {pz('mid')}
          {pose ? <Pip pose={pose} rim={seg.pip?.rim ?? 'rimR'} shadow={(seg.pip?.lift ?? 0) > 0 ? 0.2 : 0.9} /> : null}
          {pose && Over ? <PipLocal pose={pose}><Over t={t} len={len} p={p} pp={seg.pip?.overp ?? {}} id={`${id}over`} /></PipLocal> : null}
          {pose && hand && Held ? (
            <g transform={`translate(${hand.x} ${hand.y}) scale(${pose.scale})`}><Held t={t} len={len} p={p} pp={seg.pip?.heldp ?? {}} id={`${id}held`} /></g>
          ) : null}
          {pz('front')}
        </g>
      ))}
      {layer('near', setLayer('near'))}
      {!S ? <Missing what={`SET ${seg.set}`} W={W} H={H} /> : null}
      <Texts texts={seg.text ?? []} t={t} len={len} W={W} H={H} headTop={pose ? H / 2 + (pose.y - 250 * pose.scale - cam[1] * H) * cam[2] : undefined} />
    </g>
  );
};

/** shots.json segments -> the ShotMap the engine plays. */
export const makeShots = (segs: SegSpec[], W: number, H: number, reg: Registry): ShotMap =>
  Object.fromEntries(
    segs.map((seg) => {
      const Shot: React.FC<ShotProps> = (pr) => <SpecShot seg={seg} reg={reg} W={W} H={H} {...pr} />;
      return [seg.id, Shot];
    }),
  );
